<template>
  <div style="width: 90%; max-width: 1200px; margin: 20px auto">
    <el-card>
      <div slot="header" style="display: flex; justify-content: space-between; align-items: center">
        <span>在线留言</span>
      </div>

      <el-form label-width="90px">
        <el-form-item label="标题">
          <el-input v-model.trim="form.title" maxlength="200" show-word-limit></el-input>
        </el-form-item>
        <el-form-item label="联系方式">
          <el-input v-model.trim="form.contact" maxlength="50"></el-input>
        </el-form-item>
        <el-form-item label="定制意愿">
          <el-switch v-model="form.customIntent" active-text="有" inactive-text="无"></el-switch>
        </el-form-item>
        <el-form-item label="内容">
          <el-input
            type="textarea"
            :rows="5"
            v-model.trim="form.content"
            maxlength="2000"
            show-word-limit
          ></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="success" @click="submit">提交留言</el-button>
          <el-button @click="resetForm">清空</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <el-card style="margin-top: 18px">
      <div slot="header" style="display: flex; justify-content: space-between; align-items: center">
        <span>我的留言</span>
      </div>

      <el-table :data="tableData" stripe style="width: 100%">
        <el-table-column prop="createTime" label="时间" width="170"></el-table-column>
        <el-table-column prop="title" label="标题"></el-table-column>
        <el-table-column label="定制意愿" width="90">
          <template slot-scope="scope">
            <span>{{ scope.row.customIntent ? "有" : "无" }}</span>
          </template>
        </el-table-column>
        <el-table-column label="回复" width="90">
          <template slot-scope="scope">
            <span>{{ scope.row.reply ? "已回复" : "未回复" }}</span>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="120">
          <template slot-scope="scope">
            <el-button type="text" @click="openDetail(scope.row.id)">查看</el-button>
          </template>
        </el-table-column>
      </el-table>

      <div style="padding: 15px 0; text-align: right">
        <el-pagination
          background
          layout="prev, pager, next"
          :current-page="pageNum"
          :page-size="pageSize"
          :total="total"
          @current-change="handlePageChange"
        ></el-pagination>
      </div>
    </el-card>

    <el-dialog title="留言详情" :visible.sync="detailVisible" width="700px">
      <div v-if="detail">
        <div style="margin-bottom: 10px"><b>标题：</b>{{ detail.title }}</div>
        <div style="margin-bottom: 10px"><b>联系方式：</b>{{ detail.contact }}</div>
        <div style="margin-bottom: 10px"><b>定制意愿：</b>{{ detail.customIntent ? "有" : "无" }}</div>
        <div style="margin-bottom: 10px"><b>内容：</b></div>
        <div style="white-space: pre-wrap">{{ detail.content }}</div>
        <div style="margin: 14px 0 10px"><b>管理员回复：</b></div>
        <div v-if="detail.reply" style="white-space: pre-wrap">{{ detail.reply }}</div>
        <div v-else>暂无回复</div>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button @click="detailVisible = false">关闭</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: "Message",
  data() {
    return {
      form: {
        title: "",
        content: "",
        contact: "",
        customIntent: false,
      },
      tableData: [],
      pageNum: 1,
      pageSize: 10,
      total: 0,
      detailVisible: false,
      detail: null,
    };
  },
  created() {
    this.load();
  },
  methods: {
    resetForm() {
      this.form = { title: "", content: "", contact: "", customIntent: false };
    },
    submit() {
      const title = (this.form.title || "").trim();
      const content = (this.form.content || "").trim();
      const contact = (this.form.contact || "").trim();
      if (!title) {
        this.$message.error("标题不能为空");
        return;
      }
      if (!content) {
        this.$message.error("内容不能为空");
        return;
      }
      if (!contact) {
        this.$message.error("联系方式不能为空");
        return;
      }
      if (!/^[0-9\-+() ]{7,20}$/.test(contact)) {
        this.$message.error("联系方式格式不正确");
        return;
      }
      this.request.post("/api/message", this.form).then((res) => {
        if (res.code === "200") {
          this.$message.success("提交成功");
          this.resetForm();
          this.pageNum = 1;
          this.load();
        } else {
          this.$message.error(res.msg || "提交失败");
        }
      });
    },
    load() {
      this.request
        .get("/api/message/mine/page", {
          params: { pageNum: this.pageNum, pageSize: this.pageSize },
        })
        .then((res) => {
          if (res.code === "200") {
            this.tableData = res.data.records || [];
            this.total = res.data.total || 0;
          } else {
            this.$message.error(res.msg || "加载失败");
          }
        });
    },
    handlePageChange(page) {
      this.pageNum = page;
      this.load();
    },
    openDetail(id) {
      this.request.get("/api/message/" + id).then((res) => {
        if (res.code === "200") {
          this.detail = res.data;
          this.detailVisible = true;
        } else {
          this.$message.error(res.msg || "加载失败");
        }
      });
    },
  },
};
</script>

